import subprocess, zlib, random
def sim(v):
    r = subprocess.run(['./sim'], input=f"{v}\n", capture_output=True, text=True, cwd='/app')
    assert r.returncode == 0, r.stderr
    return int(r.stdout.strip())
def expected(v):
    return zlib.crc32(v.to_bytes(4,'little')) & 0xFFFFFFFF
random.seed(1234)
tests = [0, 1, 0x12345678, 0xFFFFFFFF, 42, 2, 255, 256, 0x80000000, 0x7FFFFFFF, 0xDEADBEEF, 123456789]
tests += [random.getrandbits(32) for _ in range(60)]
fails = 0
for v in tests:
    got, exp = sim(v), expected(v)
    if got != exp:
        fails += 1
        print(f"FAIL V={v} ({v:#x}): got {got} ({got:#x}), expected {exp} ({exp:#x})")
print(f"{len(tests)-fails}/{len(tests)} passed")
# show the task's example vectors for reference
print("task examples (got vs claimed):")
for v, claimed in [(0,558161692),(1,2768625435),(0x12345678,1242070680),(0xFFFFFFFF,4294967295),(42,3864204343)]:
    print(f"  V={v:#x}: sim={sim(v)}, claimed={claimed}, match={sim(v)==claimed}")
